    n_rows = len(grid)
    n_cols = len(grid[0])

    # Find separator column with value 1
    sep_col = None
    for c in range(n_cols):
        val = grid[0][c]
        if val == 1:
            if all(grid[r][c] == 1 for r in range(n_rows)):
                sep_col = c
                break

    if sep_col is None:
        return grid

    # Extract left and right grids (excluding separator)
    left = [grid[r][:sep_col] for r in range(n_rows)]
    right = [grid[r][sep_col+1:] for r in range(n_rows)]

    # If same → 3, otherwise → 4
    result = []
